PYTHONDONTWRITEBYTECODE=1 python3 -c "
from netsim.topo import TreeTopo
t=TreeTopo(depth=2,fanout=3); g=t.g; hosts=t.hosts(); sw=set(t.switches())
per_sw_pair={s:set() for s in sw}; per_sw_dst={s:set() for s in sw}
for s in hosts:
    for d in hosts:
        if s==d: continue
        for x in g.shortest_path(s,d):
            if x in sw:
                per_sw_pair[x].add((s,d)); per_sw_dst[x].add(d)
print('per-switch (src,dst)-keyed:', {k:len(v) for k,v in sorted(per_sw_pair.items())}, 'total', sum(len(v) for v in per_sw_pair.values()))
print('per-switch dst-only-keyed:', {k:len(v) for k,v in sorted(per_sw_dst.items())}, 'total', sum(len(v) for v in per_sw_dst.values()))
print('dst-only convergence time %.2f' % (36*0.1))
print('capacity check: max per switch', max(len(v) for v in per_sw_pair.values()), 'of 4096')
"
